<script setup>
import { onMounted,ref } from "vue";
import { NButton,NEmpty,NModal,NInput,NTag,NTabs,NTabPane,useDialog,useMessage } from "naive-ui";
import PageShell from "../components/PageShell.vue";import Panel from "../components/Panel.vue";
import { pluginsApi } from "../api.js";import { can } from "../access.js";
const items=ref([]),loading=ref(false),error=ref(""),open=ref(false),manifest=ref(""),piSkill=ref(""),githubUrl=ref(""),importMode=ref("manifest"),busy=ref(false);const dialog=useDialog(),message=useMessage();
async function load(){loading.value=true;error.value="";try{items.value=await pluginsApi.list();}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function install(){busy.value=true;try{if(importMode.value==='pi-skill'){await pluginsApi.importPiSkill(piSkill.value);}else if(importMode.value==='github'){await pluginsApi.importGitHubSkill(githubUrl.value);}else{let input;try{input=JSON.parse(manifest.value);}catch{throw Error("清单不是合法的 JSON，请检查格式");}await pluginsApi.import(input);}open.value=false;manifest.value="";piSkill.value="";githubUrl.value="";await load();message.success("插件已导入");}catch(e){message.error(e.message);}finally{busy.value=false;}}
async function toggle(item){busy.value=true;try{await pluginsApi.patch(item.id,!item.enabled);await load();}catch(e){message.error(e.message);}finally{busy.value=false;}}
function remove(item){dialog.warning({title:"卸载插件",content:`卸载「${item.name}」将移除其技能与 MCP 服务，确定继续？`,positiveText:"卸载",negativeText:"取消",onPositiveClick:async()=>{try{await pluginsApi.remove(item.id);await load();}catch(e){message.error(e.message);return false;}}});}onMounted(load);
</script>
<template><PageShell title="插件" subtitle="导入技能和外部工具服务" :loading="loading" :error="error"><template #actions><n-button v-if="can('workflow.write')" type="primary" @click="open=true">导入插件</n-button></template><Panel title="已安装插件"><n-empty v-if="!items.length" description="还没有安装插件" class="empty-state"/><article v-for="item in items" :key="item.id" class="plugin-row"><div><h3>{{item.name}} <n-tag size="small">{{item.version}}</n-tag></h3><p class="hint">{{item.description||'暂无说明'}}</p><p class="secondary">{{item.skills?.length??0}} 个技能 · {{item.tools?.length??0}} 个工具</p><a v-if="item.sourceUrl" :href="item.sourceUrl" target="_blank" rel="noreferrer">查看 GitHub 来源</a></div><div v-if="can('workflow.write')" class="action-row"><n-tag :type="item.enabled?'success':'default'">{{item.enabled?'已启用':'已停用'}}</n-tag><n-button :loading="busy" @click="toggle(item)">{{item.enabled?'停用':'启用'}}</n-button><n-button quaternary type="error" @click="remove(item)">卸载</n-button></div></article></Panel><n-modal v-model:show="open" preset="card" title="导入插件" style="width:640px"><n-tabs v-model:value="importMode" type="segment"><n-tab-pane name="manifest" tab="插件清单"><p class="hint">粘贴 biz-agent.plugin.v1 JSON 清单。清单不执行脚本，凭证在对应服务中单独配置。</p><n-input v-model:value="manifest" type="textarea" :autosize="{minRows:10,maxRows:20}" placeholder="粘贴插件 JSON 清单"/></n-tab-pane><n-tab-pane name="pi-skill" tab="Pi 技能"><p class="hint">粘贴 Pi Agent Skills 的 SKILL.md 内容；正文会作为技能指导书导入，不会执行脚本。</p><n-input v-model:value="piSkill" type="textarea" :autosize="{minRows:10,maxRows:20}" placeholder="---&#10;name: sales-analysis&#10;description: Analyze sales data&#10;---&#10;&#10;技能正文"/></n-tab-pane><n-tab-pane name="github" tab="GitHub"><p class="hint">导入公开仓库中的 Pi 技能目录（含 SKILL.md 和 references/assets/scripts 等资源）。文件会下载并保存到插件，脚本不会自动执行；支持 GitHub 文件页或目录链接。</p><n-input v-model:value="githubUrl" placeholder="https://github.com/owner/repo/tree/main/path/to/skill"/></n-tab-pane></n-tabs><template #footer><div class="action-row"><n-button @click="open=false">取消</n-button><n-button type="primary" :loading="busy" @click="install">导入</n-button></div></template></n-modal></PageShell></template><style scoped>.plugin-row{padding:18px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.plugin-row h3{margin:0;font-size:16px}.plugin-row a{color:var(--accent)}</style>
